// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {MerkleProof} from "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

/// @title DistributionClaimManager
/// @notice Funded, immutable, per-cycle Merkle distribution of already-acquired assets. Cycles are
///         published-and-funded atomically by the owner and are immutable thereafter: there is no
///         function to change a root, content hash, claim window, registered asset, or funded
///         amount. Participants claim their own entitlements against the frozen TASK 3 Merkle leaf
///         standard; after a cycle's deadline anyone may sweep the remaining unclaimed balance to a
///         single immutable recovery recipient. There is no pause, no arbitrary-recipient recovery,
///         no generic drain, and no upgrade surface.
/// @dev Frozen leaf (OpenZeppelin StandardMerkleTree double hash, sorted-pair tree):
///        keccak256(bytes.concat(keccak256(abi.encode(
///          block.chainid, address(this), cycleId, claimant, asset, amount))))
///      All assets, addresses, and claims exercised in this repository's tests are fictional and
///      local; nothing here is deployed or connected to any network.
contract DistributionClaimManager is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct Cycle {
        bytes32 merkleRoot;
        bytes32 allocationsContentHash;
        bytes32 manifestEnvelopeHash;
        uint64 claimStart;
        uint64 claimDeadline;
        bool published;
    }

    struct AssetFunding {
        bool registered;
        uint256 funded;
        uint256 claimed;
        uint256 recovered;
        bool recoveryClosed;
    }

    /// @notice A single claim within a batch; the claimant is always msg.sender.
    struct ClaimRequest {
        address asset;
        uint256 amount;
        bytes32[] proof;
    }

    /// @notice Immutable destination for all post-deadline recoveries. Set once at construction.
    address public immutable recoveryRecipient;

    /// @notice Published cycles by id. Immutable once `published` is true.
    mapping(uint256 cycleId => Cycle) public cycles;

    /// @notice Per-cycle, per-asset funding and consumption accounting.
    mapping(uint256 cycleId => mapping(address asset => AssetFunding)) public assetFunding;

    /// @notice Whether a given (cycle, claimant, asset) entitlement has been consumed.
    mapping(uint256 cycleId => mapping(address claimant => mapping(address asset => bool))) public
        claimed;

    /// @notice Total outstanding participant liability per token across every cycle.
    mapping(address token => uint256) public totalOutstanding;

    event CyclePublished(
        uint256 indexed cycleId,
        bytes32 merkleRoot,
        bytes32 allocationsContentHash,
        bytes32 manifestEnvelopeHash,
        uint64 claimStart,
        uint64 claimDeadline,
        uint256 assetCount
    );
    event CycleAssetFunded(uint256 indexed cycleId, address indexed asset, uint256 amount);
    event Claimed(
        uint256 indexed cycleId, address indexed claimant, address indexed asset, uint256 amount
    );
    event ExpiredRecovered(
        uint256 indexed cycleId,
        address indexed asset,
        address indexed recoveryRecipient,
        uint256 amount
    );

    error ZeroAddress();
    error CycleAlreadyPublished(uint256 cycleId);
    error CycleNotFound(uint256 cycleId);
    error ZeroRoot();
    error ZeroContentHash();
    error InvalidClaimWindow();
    error EmptyAssetList();
    error ArrayLengthMismatch();
    error ZeroAsset();
    error ZeroFundingAmount();
    error DuplicateAsset(address asset);
    error FundingAmountMismatch(address asset, uint256 declared, uint256 received);
    error AssetNotRegistered(uint256 cycleId, address asset);
    error ClaimNotStarted();
    error ClaimExpired();
    error ZeroClaimAmount();
    error AlreadyClaimed(uint256 cycleId, address claimant, address asset);
    error InvalidProof();
    error InsufficientCycleFunding(uint256 cycleId, address asset);
    error EmptyBatch();
    error RecoveryTooEarly();
    error AlreadyRecovered(uint256 cycleId, address asset);

    /// @param initialOwner Two-step owner (represents future governance; fictional/local here).
    /// @param recoveryRecipient_ Immutable destination for post-deadline recoveries. Nonzero.
    constructor(address initialOwner, address recoveryRecipient_) Ownable(initialOwner) {
        if (recoveryRecipient_ == address(0)) revert ZeroAddress();
        recoveryRecipient = recoveryRecipient_;
    }

    // --- Leaf calculation (frozen TASK 3 standard) --------------------------------------------

    /// @notice The Merkle leaf for an entitlement, bound to this chain and this manager.
    function leafFor(uint256 cycleId, address claimant, address asset, uint256 amount)
        external
        view
        returns (bytes32)
    {
        return _leaf(cycleId, claimant, asset, amount);
    }

    function _leaf(uint256 cycleId, address claimant, address asset, uint256 amount)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            bytes.concat(
                keccak256(
                    abi.encode(block.chainid, address(this), cycleId, claimant, asset, amount)
                )
            )
        );
    }

    // --- Publication (owner only, atomic exact funding) ---------------------------------------

    /// @notice Publish and fully fund an immutable cycle in a single atomic transaction.
    /// @dev fundedAmounts are the TASK 3 `allocated` participant entitlements only — never the
    ///      strategic reserve, distribution dust, full participant pool, or other inventory. Each
    ///      asset is pulled from msg.sender via SafeERC20 and the received balance delta must equal
    ///      the declared amount exactly (fee-on-transfer / short transfers revert the whole call).
    function publishCycle(
        uint256 cycleId,
        bytes32 merkleRoot,
        bytes32 allocationsContentHash,
        bytes32 manifestEnvelopeHash,
        uint64 claimStart,
        uint64 claimDeadline,
        address[] calldata assets,
        uint256[] calldata fundedAmounts
    ) external onlyOwner nonReentrant {
        if (cycles[cycleId].published) {
            revert CycleAlreadyPublished(cycleId);
        }
        if (merkleRoot == bytes32(0)) revert ZeroRoot();
        if (allocationsContentHash == bytes32(0) || manifestEnvelopeHash == bytes32(0)) {
            revert ZeroContentHash();
        }
        // Claim windows are intentionally gated on block.timestamp; second-level validator drift
        // is negligible against multi-hour/day windows.
        // forge-lint: disable-next-line(block-timestamp)
        if (claimStart <= block.timestamp) revert InvalidClaimWindow();
        if (claimDeadline <= claimStart) revert InvalidClaimWindow();
        if (assets.length == 0) revert EmptyAssetList();
        if (assets.length != fundedAmounts.length) revert ArrayLengthMismatch();

        cycles[cycleId] = Cycle({
            merkleRoot: merkleRoot,
            allocationsContentHash: allocationsContentHash,
            manifestEnvelopeHash: manifestEnvelopeHash,
            claimStart: claimStart,
            claimDeadline: claimDeadline,
            published: true
        });

        emit CyclePublished(
            cycleId,
            merkleRoot,
            allocationsContentHash,
            manifestEnvelopeHash,
            claimStart,
            claimDeadline,
            assets.length
        );

        for (uint256 i = 0; i < assets.length; i++) {
            _fundAsset(cycleId, assets[i], fundedAmounts[i]);
        }
    }

    /// @dev Register and exactly fund one asset for a cycle. Extracted to keep `publishCycle`
    ///      within the stack limit. Pulls tokens from msg.sender (the owner publishing the cycle).
    function _fundAsset(uint256 cycleId, address asset, uint256 amount) internal {
        if (asset == address(0)) revert ZeroAsset();
        if (amount == 0) revert ZeroFundingAmount();

        AssetFunding storage af = assetFunding[cycleId][asset];
        if (af.registered) revert DuplicateAsset(asset);
        af.registered = true;
        af.funded = amount;

        IERC20 token = IERC20(asset);
        uint256 balanceBefore = token.balanceOf(address(this));
        token.safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = token.balanceOf(address(this)) - balanceBefore;
        if (received != amount) revert FundingAmountMismatch(asset, amount, received);

        totalOutstanding[asset] += amount;
        emit CycleAssetFunded(cycleId, asset, amount);
    }

    // --- Claims -------------------------------------------------------------------------------

    /// @notice Claim a single entitlement for msg.sender.
    function claim(uint256 cycleId, address asset, uint256 amount, bytes32[] calldata proof)
        external
        nonReentrant
    {
        _claim(cycleId, msg.sender, asset, amount, proof);
    }

    /// @notice Claim multiple entitlements for msg.sender within one cycle, atomically.
    function claimBatch(uint256 cycleId, ClaimRequest[] calldata claims_) external nonReentrant {
        if (claims_.length == 0) revert EmptyBatch();
        for (uint256 i = 0; i < claims_.length; i++) {
            _claim(cycleId, msg.sender, claims_[i].asset, claims_[i].amount, claims_[i].proof);
        }
    }

    function _claim(
        uint256 cycleId,
        address claimant,
        address asset,
        uint256 amount,
        bytes32[] calldata proof
    ) internal {
        if (amount == 0) revert ZeroClaimAmount();
        Cycle storage c = cycles[cycleId];
        if (!c.published) revert CycleNotFound(cycleId);
        AssetFunding storage af = assetFunding[cycleId][asset];
        if (!af.registered) revert AssetNotRegistered(cycleId, asset);
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp < c.claimStart) revert ClaimNotStarted();
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp > c.claimDeadline) revert ClaimExpired();
        if (claimed[cycleId][claimant][asset]) revert AlreadyClaimed(cycleId, claimant, asset);

        bytes32 leaf = _leaf(cycleId, claimant, asset, amount);
        if (!MerkleProof.verify(proof, c.merkleRoot, leaf)) revert InvalidProof();

        // Remaining liability must cover this claim.
        if (amount > af.funded - af.claimed - af.recovered) {
            revert InsufficientCycleFunding(cycleId, asset);
        }

        // Effects before interaction: mark consumed, update accounting, then transfer.
        claimed[cycleId][claimant][asset] = true;
        af.claimed += amount;
        totalOutstanding[asset] -= amount;

        IERC20(asset).safeTransfer(claimant, amount);
        emit Claimed(cycleId, claimant, asset, amount);
    }

    // --- Post-deadline recovery (permissionless; fixed destination) ---------------------------

    /// @notice After a cycle's deadline, sweep the remaining unclaimed balance of one cycle asset
    ///         to the immutable recovery recipient. Callable by anyone; the caller cannot choose
    ///         the destination or the amount (both derive from recorded accounting).
    function recoverExpired(uint256 cycleId, address asset) external nonReentrant {
        Cycle storage c = cycles[cycleId];
        if (!c.published) revert CycleNotFound(cycleId);
        AssetFunding storage af = assetFunding[cycleId][asset];
        if (!af.registered) revert AssetNotRegistered(cycleId, asset);
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp <= c.claimDeadline) revert RecoveryTooEarly();
        if (af.recoveryClosed) revert AlreadyRecovered(cycleId, asset);

        uint256 remainingAmount = af.funded - af.claimed - af.recovered;

        // Effects before interaction.
        af.recovered += remainingAmount;
        af.recoveryClosed = true;
        totalOutstanding[asset] -= remainingAmount;

        emit ExpiredRecovered(cycleId, asset, recoveryRecipient, remainingAmount);
        if (remainingAmount > 0) {
            IERC20(asset).safeTransfer(recoveryRecipient, remainingAmount);
        }
    }

    // --- Views --------------------------------------------------------------------------------

    /// @notice Remaining unclaimed, unrecovered liability for a cycle asset.
    function remaining(uint256 cycleId, address asset) external view returns (uint256) {
        AssetFunding storage af = assetFunding[cycleId][asset];
        return af.funded - af.claimed - af.recovered;
    }
}

src/DistributionFundingCoordinator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IStockAcquisitionVaultOps} from "./interfaces/IStockAcquisitionVaultOps.sol";
import {IDistributionClaimManagerFunding} from "./interfaces/IDistributionClaimManagerFunding.sol";

/// @title DistributionFundingCoordinator
/// @notice Binds each stock acquisition to exactly one distribution cycle, sourcing every amount from
///         the frozen `StockAcquisitionVault`'s own on-chain accounting rather than any caller-reported
///         value. The coordinator occupies BOTH of the frozen vault's immutable roles — its
///         `acquisitionExecutor` and its `distributionFundingCoordinator` (the frozen constructor
///         permits `acquisitionExecutor == distributionFundingCoordinator`). As the sole executor it is
///         the ONLY contract that can move the vault's acquisition counters, so it records each
///         acquisition atomically from the vault's exact before/after cumulative deltas, assigns a
///         monotonic acquisition id, and later releases-and-funds exactly that recorded 80% once,
///         bound to one claim-cycle id. This preserves the frozen vault while closing the
///         per-acquisition acceptance gap.
/// @dev Non-upgradeable and minimal in authority: NO owner, NO mutable setter, NO arbitrary recipient,
///      NO withdrawal/sweep/rescue, NO generic call, NO custody beyond same-transaction transit, NO
///      caller-selected token or amount, and no support for tokens outside the vault's frozen approved
///      basket. Two trusted immutable roles remain a documented restricted-beta dependency:
///      `acquisitionOperator` (supplies the off-chain Rialto quote and `minStockOut` and initiates
///      acquisitions — safe permissionless minimum-price enforcement is not yet available) and
///      `rootPublisher` (supplies the governed Proof-of-Distribution root/window). The coordinator is
///      the frozen claim manager's owner (set at deployment via a predicted address — no setter).
///
///      State machine per acquisition id: NONE -> RECORDED (on `executeAndRecordAcquisition`) ->
///      FUNDED (on `fundRecordedAcquisition`). No state permits tokens to be withdrawn or redirected;
///      the RECORDED->FUNDED transition releases exactly the recorded amount to the coordinator and
///      immediately funds the claim manager in the same transaction, verified by exact balance deltas.
///
///      DEPLOYMENT IS NOT AUTHORIZED here. The vault<->coordinator immutability is circular (the frozen
///      vault stores this coordinator immutably for both roles and this coordinator stores the vault
///      immutably), resolved by nonce-predicted CREATE with on-chain immutable verification, no
///      one-time setter. The constructor code-checks the claim manager (already deployed) but not the
///      vault (predicted). There is NO native-ETH receive/fallback. All assets/addresses/cycles in this
///      repository's tests are fictional and local; nothing is deployed and no PoD root is fabricated.
contract DistributionFundingCoordinator is ReentrancyGuard {
    using SafeERC20 for IERC20;

    IStockAcquisitionVaultOps public immutable stockAcquisitionVault;
    IDistributionClaimManagerFunding public immutable distributionClaimManager;
    /// @notice Trusted keeper that initiates acquisitions (supplies the off-chain quote + minStockOut).
    address public immutable acquisitionOperator;
    /// @notice Governed publisher that supplies the Proof-of-Distribution root/window and funds cycles.
    address public immutable rootPublisher;

    enum AcquisitionStatus {
        NONE,
        RECORDED,
        FUNDED
    }

    /// @notice The exact per-acquisition record, derived only from the vault's observed deltas.
    struct AcquisitionRecord {
        AcquisitionStatus status;
        address stockToken;
        uint256 wethSpent;
        uint256 acquiredStock;
        uint256 distributionAmount; // exact 80% (vault rule)
        uint256 reserveAmount; // exact 20% + remainder (delivered by the vault to its reserve recipient)
        uint256 cycleId; // set on funding
    }

    /// @notice Acquisition records by monotonic id (ids start at 1; 0 is never a valid acquisition).
    mapping(uint256 acquisitionId => AcquisitionRecord) public acquisitions;
    /// @notice The last assigned acquisition id (next id is `acquisitionCount + 1`).
    uint256 public acquisitionCount;
    /// @notice Whether a claim-cycle id has already been bound to an acquisition.
    mapping(uint256 cycleId => bool) public cycleUsed;
    /// @notice The acquisition id bound to a claim-cycle id (0 if unused).
    mapping(uint256 cycleId => uint256) public cycleAcquisitionId;

    event AcquisitionRecorded(
        uint256 indexed acquisitionId,
        address indexed stockToken,
        address indexed operator,
        uint256 wethSpent,
        uint256 acquiredStock,
        uint256 distributionAmount,
        uint256 reserveAmount
    );
    event AcquisitionFunded(
        uint256 indexed acquisitionId,
        uint256 indexed cycleId,
        address indexed stockToken,
        uint256 amount,
        bytes32 merkleRoot,
        uint64 claimStart,
        uint64 claimDeadline
    );

    error ZeroAddress();
    error InvalidSystemAddress();
    error NotAContract(address target);
    error NotAcquisitionOperator();
    error NotRootPublisher();
    error StockNotApproved(address stockToken);
    error ZeroAmountIn();
    error ZeroMinimumOutput();
    error ExpiredDeadline();
    error WethSpendMismatch(uint256 expected, uint256 actual);
    error ZeroAcquired();
    error DistributionRuleMismatch(uint256 expected, uint256 actual);
    error ReserveRuleMismatch(uint256 expected, uint256 actual);
    error UnexpectedRelease(uint256 delta);
    error AcquisitionNotRecorded(uint256 acquisitionId);
    error CycleAlreadyUsed(uint256 cycleId);
    error ReleaseDeltaMismatch(uint256 expected, uint256 actual);
    error CoordinatorReceiptMismatch(uint256 expected, uint256 actual);
    error ReserveAccountingChanged(uint256 before, uint256 afterBalance);
    error CoordinatorResidue(uint256 baseline, uint256 afterBalance);
    error ManagerReceiptMismatch(uint256 expected, uint256 actual);
    error AllowanceNotCleared(uint256 remaining);

    /// @param vault_ Immutable StockAcquisitionVault (may be a pre-computed address without code yet;
    ///        this coordinator must be BOTH its acquisitionExecutor and distributionFundingCoordinator).
    /// @param claimManager_ Immutable DistributionClaimManager (must already have code; this
    ///        coordinator must be its owner, set at deployment via the manager's `initialOwner`).
    /// @param acquisitionOperator_ Immutable trusted keeper authorized to initiate acquisitions.
    /// @param rootPublisher_ Immutable governed publisher authorized to fund cycles.
    constructor(
        address vault_,
        address claimManager_,
        address acquisitionOperator_,
        address rootPublisher_
    ) {
        if (
            vault_ == address(0) || claimManager_ == address(0)
                || acquisitionOperator_ == address(0) || rootPublisher_ == address(0)
        ) {
            revert ZeroAddress();
        }
        if (
            vault_ == claimManager_ || vault_ == acquisitionOperator_ || vault_ == rootPublisher_
                || claimManager_ == acquisitionOperator_ || claimManager_ == rootPublisher_
        ) {
            revert InvalidSystemAddress();
        }
        if (claimManager_.code.length == 0) revert NotAContract(claimManager_);

        stockAcquisitionVault = IStockAcquisitionVaultOps(vault_);
        distributionClaimManager = IDistributionClaimManagerFunding(claimManager_);
        acquisitionOperator = acquisitionOperator_;
        rootPublisher = rootPublisher_;
    }

    // Snapshot of the vault's cumulative counters, taken before and after a single executeAcquisition.
    struct Counters {
        uint256 wethSpent;
        uint256 acquired;
        uint256 distribution;
        uint256 reserve;
        uint256 released;
    }

    /// @notice Initiate a vault acquisition and record it atomically from the vault's exact deltas.
    /// @dev acquisitionOperator-only, `nonReentrant`. The coordinator is the vault's sole executor, so
    ///      no other party can move the counters and the before/after deltas are exactly this
    ///      acquisition's contribution. A hostile/reverting acquisition reverts the whole call — no
    ///      record is written and no id is consumed. Every recorded amount is derived from storage
    ///      deltas; no caller-reported acquired/distribution amount is trusted.
    function executeAndRecordAcquisition(
        address stockToken,
        uint256 wethAmountIn,
        uint256 minStockOut,
        uint256 deadline,
        bytes calldata executionData
    ) external nonReentrant returns (uint256 acquisitionId) {
        if (msg.sender != acquisitionOperator) {
            revert NotAcquisitionOperator();
        }
        if (!stockAcquisitionVault.isApprovedStockToken(stockToken)) {
            revert StockNotApproved(stockToken);
        }
        if (wethAmountIn == 0) revert ZeroAmountIn();
        if (minStockOut == 0) revert ZeroMinimumOutput();
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp > deadline) revert ExpiredDeadline();

        Counters memory b = _readCounters(stockToken);
        stockAcquisitionVault.executeAcquisition(
            stockToken, wethAmountIn, minStockOut, deadline, executionData
        );
        AcquisitionRecord memory rec =
            _deriveRecord(stockToken, wethAmountIn, b, _readCounters(stockToken));

        acquisitionId = ++acquisitionCount;
        acquisitions[acquisitionId] = rec;

        emit AcquisitionRecorded(
            acquisitionId,
            stockToken,
            msg.sender,
            rec.wethSpent,
            rec.acquiredStock,
            rec.distributionAmount,
            rec.reserveAmount
        );
    }

    /// @dev Validate the vault's before/after deltas against its frozen 80/20 rule and build the record.
    ///      Reverts unless the WETH spend matches exactly, some stock was acquired, the distribution
    ///      delta equals the vault's overflow-safe 80%, the reserve delta is the exact remainder, and no
    ///      release happened during the acquisition.
    function _deriveRecord(
        address stockToken,
        uint256 wethAmountIn,
        Counters memory b,
        Counters memory a
    ) internal view returns (AcquisitionRecord memory rec) {
        uint256 wethDelta = a.wethSpent - b.wethSpent;
        uint256 acquiredDelta = a.acquired - b.acquired;
        uint256 distDelta = a.distribution - b.distribution;
        uint256 resDelta = a.reserve - b.reserve;

        if (wethDelta != wethAmountIn) revert WethSpendMismatch(wethAmountIn, wethDelta);
        if (acquiredDelta == 0) revert ZeroAcquired();
        uint256 expectedDist = Math.mulDiv(
            acquiredDelta,
            stockAcquisitionVault.DISTRIBUTION_PERCENT(),
            stockAcquisitionVault.SPLIT_DENOMINATOR()
        );
        if (distDelta != expectedDist) revert DistributionRuleMismatch(expectedDist, distDelta);
        if (resDelta != acquiredDelta - expectedDist) {
            revert ReserveRuleMismatch(acquiredDelta - expectedDist, resDelta);
        }
        if (a.released - b.released != 0) revert UnexpectedRelease(a.released - b.released);

        rec = AcquisitionRecord({
            status: AcquisitionStatus.RECORDED,
            stockToken: stockToken,
            wethSpent: wethDelta,
            acquiredStock: acquiredDelta,
            distributionAmount: distDelta,
            reserveAmount: resDelta,
            cycleId: 0
        });
    }

    function _readCounters(address stockToken) internal view returns (Counters memory c) {
        c.wethSpent = stockAcquisitionVault.totalWethSpent();
        c.acquired = stockAcquisitionVault.totalStockAcquired(stockToken);
        c.distribution = stockAcquisitionVault.distributionAllocated(stockToken);
        c.reserve = stockAcquisitionVault.reserveAllocated(stockToken);
        c.released = stockAcquisitionVault.distributionReleased(stockToken);
    }

    // Governed Proof-of-Distribution publication inputs, packed to keep the entry within the stack.
    struct PublishInputs {
        uint256 cycleId;
        bytes32 merkleRoot;
        bytes32 allocationsContentHash;
        bytes32 manifestEnvelopeHash;
        uint64 claimStart;
        uint64 claimDeadline;
    }

    /// @notice Release and fund exactly the recorded 80% distribution for `acquisitionId`, bound to one
    ///         claim-cycle id. No caller-selected token or amount — both come from the stored record.
    /// @dev rootPublisher-only, `nonReentrant`. RECORDED -> FUNDED. Releases the exact recorded amount
    ///      from the vault to this coordinator (it is the vault's distributionFundingCoordinator), then
    ///      publishes-and-funds the cycle, verifying every balance delta and returning the coordinator
    ///      to its pre-release baseline (donations preserved). Reserve accounting must not change.
    function fundRecordedAcquisition(
        uint256 acquisitionId,
        bytes32 merkleRoot,
        bytes32 allocationsContentHash,
        bytes32 manifestEnvelopeHash,
        uint64 claimStart,
        uint64 claimDeadline,
        uint256 cycleId
    ) external nonReentrant {
        if (msg.sender != rootPublisher) revert NotRootPublisher();
        AcquisitionRecord storage rec = acquisitions[acquisitionId];
        if (rec.status != AcquisitionStatus.RECORDED) revert AcquisitionNotRecorded(acquisitionId);
        if (cycleUsed[cycleId]) revert CycleAlreadyUsed(cycleId);

        address stockToken = rec.stockToken;
        uint256 amount = rec.distributionAmount;

        // Effects before interaction (state machine advance + one-cycle-per-acquisition binding).
        rec.status = AcquisitionStatus.FUNDED;
        rec.cycleId = cycleId;
        cycleUsed[cycleId] = true;
        cycleAcquisitionId[cycleId] = acquisitionId;

        _releaseAndFund(
            PublishInputs({
                cycleId: cycleId,
                merkleRoot: merkleRoot,
                allocationsContentHash: allocationsContentHash,
                manifestEnvelopeHash: manifestEnvelopeHash,
                claimStart: claimStart,
                claimDeadline: claimDeadline
            }),
            acquisitionId,
            stockToken,
            amount
        );
    }

    function _releaseAndFund(
        PublishInputs memory p,
        uint256 acquisitionId,
        address stockToken,
        uint256 amount
    ) internal {
        uint256 coordBaseline = IERC20(stockToken).balanceOf(address(this));
        _releaseExact(stockToken, amount, coordBaseline);
        _publishExact(p, stockToken, amount, coordBaseline);

        emit AcquisitionFunded(
            acquisitionId,
            p.cycleId,
            stockToken,
            amount,
            p.merkleRoot,
            p.claimStart,
            p.claimDeadline
        );
    }

    /// @dev Release exactly `amount` from the vault to this coordinator (its immutable
    ///      distributionFundingCoordinator) and verify the vault released exactly that, the coordinator
    ///      received exactly that, and the vault's reserve accounting did not move.
    function _releaseExact(address stockToken, uint256 amount, uint256 coordBaseline) internal {
        uint256 relBefore = stockAcquisitionVault.distributionReleased(stockToken);
        uint256 resBefore = stockAcquisitionVault.reserveAllocated(stockToken);

        stockAcquisitionVault.releaseToDistributionCoordinator(stockToken, amount);

        uint256 relDelta = stockAcquisitionVault.distributionReleased(stockToken) - relBefore;
        if (relDelta != amount) revert ReleaseDeltaMismatch(amount, relDelta);
        uint256 coordReceived = IERC20(stockToken).balanceOf(address(this)) - coordBaseline;
        if (coordReceived != amount) revert CoordinatorReceiptMismatch(amount, coordReceived);
        uint256 resAfter = stockAcquisitionVault.reserveAllocated(stockToken);
        if (resAfter != resBefore) revert ReserveAccountingChanged(resBefore, resAfter);
    }

    /// @dev Publish-and-fund exactly `amount` into the claim manager, then verify the manager received
    ///      exactly that, the coordinator returned to its pre-release baseline (donations preserved),
    ///      and the manager's allowance is cleared.
    function _publishExact(
        PublishInputs memory p,
        address stockToken,
        uint256 amount,
        uint256 coordBaseline
    ) internal {
        uint256 mgrBefore = IERC20(stockToken).balanceOf(address(distributionClaimManager));

        address[] memory assets = new address[](1);
        assets[0] = stockToken;
        uint256[] memory amounts = new uint256[](1);
        amounts[0] = amount;

        IERC20(stockToken).forceApprove(address(distributionClaimManager), amount);
        distributionClaimManager.publishCycle(
            p.cycleId,
            p.merkleRoot,
            p.allocationsContentHash,
            p.manifestEnvelopeHash,
            p.claimStart,
            p.claimDeadline,
            assets,
            amounts
        );
        IERC20(stockToken).forceApprove(address(distributionClaimManager), 0);

        uint256 coordAfter = IERC20(stockToken).balanceOf(address(this));
        if (coordAfter != coordBaseline) revert CoordinatorResidue(coordBaseline, coordAfter);
        uint256 mgrReceived =
            IERC20(stockToken).balanceOf(address(distributionClaimManager)) - mgrBefore;
        if (mgrReceived != amount) revert ManagerReceiptMismatch(amount, mgrReceived);
        uint256 remaining =
            IERC20(stockToken).allowance(address(this), address(distributionClaimManager));
        if (remaining != 0) revert AllowanceNotCleared(remaining);
    }
}

src/StockAcquisitionVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IStockAcquisitionAdapter} from "./interfaces/IStockAcquisitionAdapter.sol";

/// @title StockAcquisitionVault
/// @notice Custodies the WETH stock-acquisition budget delivered by `BPSTradeRouter` (as the router's
///         immutable `stockBudgetRecipient`) and converts it, on the authority of a single immutable
///         executor, into an approved stock token through an immutable acquisition adapter. Each
///         successful acquisition applies the frozen 80/20 split: 80% (floored) is retained as the
///         distribution allocation (releasable only to the immutable DistributionFundingCoordinator),
///         and the remaining 20% plus the entire rounding remainder is delivered to the immutable
///         protocol reserve recipient.
/// @dev Non-upgradeable and deliberately minimal in authority. There is NO owner, NO pause, NO
///      arbitrary-recipient parameter, NO owner/executor withdrawal, NO generic sweep, NO arbitrary
///      call, NO proxy/initializer/delegatecall, and NO stock-token recovery to a discretionary
///      address. The only WETH outflow is `executeAcquisition`, which can only approve and call the
///      immutable adapter for the exact input and only credits an approved stock token verified by an
///      independent balance delta. The only stock outflow is the reserve delivery inside an
///      acquisition (to the immutable reserve recipient) and `releaseToDistributionCoordinator` (to
///      the immutable coordinator). The approved stock basket is frozen at construction with no
///      add/remove function.
///
///      DEPLOYMENT IS BLOCKED for now: the `DistributionFundingCoordinator` is a later task (6B-2 /
///      the coordinator task). This vault only implements the narrow immutable-recipient release
///      boundary — transferring the distribution allocation to the coordinator address. It does NOT
///      publish or fund `DistributionClaimManager` cycles; a bare transfer to the coordinator does
///      not complete any distribution. A production deployment must wait until the concrete
///      coordinator address and the full ownership/authorization sequence (executor = governance
///      keeper, reserve/coordinator = finalized destinations) are settled and independently verified.
///
///      All assets, addresses, adapters, and acquisitions exercised in this repository's tests are
///      fictional and local; nothing here is deployed or connected to any network.
contract StockAcquisitionVault is ReentrancyGuard {
    using SafeERC20 for IERC20;

    // --- Frozen 80/20 split (percent, denominator 100) ------------------------------------------

    uint256 public constant SPLIT_DENOMINATOR = 100;
    uint256 public constant DISTRIBUTION_PERCENT = 80; // 80% distribution; remainder (>=20%) reserve

    // --- Immutable configuration -----------------------------------------------------------------

    IERC20 public immutable weth;
    IStockAcquisitionAdapter public immutable acquisitionAdapter;
    /// @notice The only address allowed to execute acquisitions and release distribution stock.
    address public immutable acquisitionExecutor;
    /// @notice Immutable destination for the reserve (>=20%) portion of every acquisition.
    address public immutable reserveRecipient;
    /// @notice Immutable destination for released distribution stock. Placeholder until the concrete
    ///         DistributionFundingCoordinator exists (see contract-level NatSpec — deployment blocked).
    address public immutable distributionFundingCoordinator;

    /// @notice Frozen approved stock basket (set once at construction; no add/remove in v1).
    mapping(address stockToken => bool approved) public isApprovedStockToken;
    address[] private _approvedStockTokens;

    // --- Accounting (attributed protocol amounts; never raw balances) ---------------------------

    /// @notice Total WETH actually spent on acquisitions (declared input, verified as exact spend).
    uint256 public totalWethSpent;
    /// @notice Total stock actually acquired per token (verified balance delta), before the split.
    mapping(address stockToken => uint256) public totalStockAcquired;
    /// @notice Accounted distribution allocation per token (80%, floored), retained in the vault.
    mapping(address stockToken => uint256) public distributionAllocated;
    /// @notice Reserve allocation per token (remainder) delivered to the reserve recipient.
    mapping(address stockToken => uint256) public reserveAllocated;
    /// @notice Distribution stock per token released to the coordinator.
    mapping(address stockToken => uint256) public distributionReleased;

    // --- Events ----------------------------------------------------------------------------------

    event StockAcquired(
        address indexed executor,
        address indexed stockToken,
        uint256 wethAmountIn,
        uint256 actualStockOut,
        uint256 distributionAllocation,
        uint256 reserveAllocation,
        address adapter
    );
    event ReserveAllocated(
        address indexed stockToken, address indexed reserveRecipient, uint256 amount
    );
    event DistributionReleased(
        address indexed stockToken, address indexed coordinator, uint256 amount
    );

    // --- Errors ----------------------------------------------------------------------------------

    error ZeroAddress();
    error InvalidSystemAddress();
    error DuplicateStockToken(address stockToken);
    error EmptyBasket();
    error NotAuthorizedExecutor();
    error StockTokenNotApproved(address stockToken);
    error ZeroAmount();
    error ZeroMinimumOutput();
    error ExpiredDeadline();
    error InsufficientWethCustody(uint256 requested, uint256 available);
    error WethSpendMismatch(uint256 expected, uint256 actual);
    error MinimumStockOutNotMet(uint256 minimum, uint256 actual);
    error ReportedStockMismatch(uint256 reported, uint256 observed);
    error ReserveDeliveryMismatch(uint256 expected, uint256 received);
    error DistributionDeliveryMismatch(uint256 expected, uint256 received);
    error ReleaseExceedsAllocation(uint256 requested, uint256 releasable);
    error NativeTransferNotAllowed();
    /// @dev The adapter finished holding more WETH than it started with (retained input rather than
    ///      consuming it in the acquisition). `before`/`afterBalance` are the adapter's WETH balances.
    error ResidualWethInAdapter(uint256 before, uint256 afterBalance);
    /// @dev The adapter finished holding more of the selected stock token than it started with
    ///      (skimmed acquired stock instead of delivering all of it to the vault).
    error ResidualStockInAdapter(uint256 before, uint256 afterBalance);

    /// @param weth_ Immutable WETH token (the acquisition budget asset).
    /// @param acquisitionAdapter_ Immutable adapter that converts WETH into an approved stock token.
    /// @param acquisitionExecutor_ Immutable executor (future governance keeper) — sole authority.
    /// @param reserveRecipient_ Immutable reserve (>=20%) destination.
    /// @param distributionFundingCoordinator_ Immutable distribution-release destination (placeholder).
    /// @param approvedStockTokens_ Frozen approved basket (nonempty, unique, non-aliasing).
    constructor(
        address weth_,
        address acquisitionAdapter_,
        address acquisitionExecutor_,
        address reserveRecipient_,
        address distributionFundingCoordinator_,
        address[] memory approvedStockTokens_
    ) {
        if (
            weth_ == address(0) || acquisitionAdapter_ == address(0)
                || acquisitionExecutor_ == address(0) || reserveRecipient_ == address(0)
                || distributionFundingCoordinator_ == address(0)
        ) {
            revert ZeroAddress();
        }
        // The adapter must not alias WETH or this vault; the reserve and coordinator must be distinct
        // real destinations, not the vault/adapter/WETH or each other.
        if (acquisitionAdapter_ == weth_ || acquisitionAdapter_ == address(this)) {
            revert InvalidSystemAddress();
        }
        if (
            reserveRecipient_ == address(this) || reserveRecipient_ == acquisitionAdapter_
                || reserveRecipient_ == weth_
        ) {
            revert InvalidSystemAddress();
        }
        if (
            distributionFundingCoordinator_ == address(this)
                || distributionFundingCoordinator_ == acquisitionAdapter_
                || distributionFundingCoordinator_ == weth_
                || distributionFundingCoordinator_ == reserveRecipient_
        ) {
            revert InvalidSystemAddress();
        }
        if (approvedStockTokens_.length == 0) revert EmptyBasket();

        weth = IERC20(weth_);
        acquisitionAdapter = IStockAcquisitionAdapter(acquisitionAdapter_);
        acquisitionExecutor = acquisitionExecutor_;
        reserveRecipient = reserveRecipient_;
        distributionFundingCoordinator = distributionFundingCoordinator_;

        for (uint256 i = 0; i < approvedStockTokens_.length; i++) {
            address token = approvedStockTokens_[i];
            if (token == address(0)) revert ZeroAddress();
            if (
                token == weth_ || token == acquisitionAdapter_ || token == address(this)
                    || token == acquisitionExecutor_ || token == reserveRecipient_
                    || token == distributionFundingCoordinator_
            ) {
                revert InvalidSystemAddress();
            }
            if (isApprovedStockToken[token]) revert DuplicateStockToken(token);
            isApprovedStockToken[token] = true;
            _approvedStockTokens.push(token);
        }
    }

    /// @dev Reject direct native-ETH transfers; the vault only ever moves ERC-20 WETH and stock.
    receive() external payable {
        revert NativeTransferNotAllowed();
    }

    // --- Acquisition (executor only) -------------------------------------------------------------

    // Intermediate acquisition state held in memory to keep the function within the stack limit.
    struct AcquireVars {
        uint256 wethBefore; // vault WETH before the adapter call
        uint256 stockBefore; // vault selected-stock before the adapter call
        uint256 adapterWethBefore; // adapter WETH before the adapter call (donation-tolerant baseline)
        uint256 adapterStockBefore; // adapter selected-stock before the adapter call (baseline)
        uint256 reported;
        uint256 actualStockOut;
        uint256 distributionAllocation;
        uint256 reserveAllocation;
    }

    /// @notice Convert exactly `wethAmountIn` of custodied WETH into `stockToken` via the immutable
    ///         adapter, then split the verified output 80/20 (distribution retained, reserve sent).
    /// @dev Executor-only, nonReentrant. Approves the adapter for exactly the input and clears it
    ///      after; independently verifies the exact WETH spent, the actual stock delta, and that the
    ///      adapter's report equals the observed delta; reverts atomically on any mismatch. No target,
    ///      recipient, asset, or call is caller-controlled beyond the approved `stockToken`.
    function executeAcquisition(
        address stockToken,
        uint256 wethAmountIn,
        uint256 minStockOut,
        uint256 deadline,
        bytes calldata executionData
    ) external nonReentrant returns (uint256 actualStockOut) {
        if (msg.sender != acquisitionExecutor) {
            revert NotAuthorizedExecutor();
        }
        if (!isApprovedStockToken[stockToken]) revert StockTokenNotApproved(stockToken);
        if (wethAmountIn == 0) revert ZeroAmount();
        if (minStockOut == 0) revert ZeroMinimumOutput();
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp > deadline) revert ExpiredDeadline();

        AcquireVars memory v;
        v.wethBefore = weth.balanceOf(address(this));
        if (v.wethBefore < wethAmountIn) {
            revert InsufficientWethCustody(wethAmountIn, v.wethBefore);
        }
        v.stockBefore = IERC20(stockToken).balanceOf(address(this));
        // Donation-tolerant baselines: the adapter's own WETH and selected-stock balances at entry.
        // A correct pass-through adapter finishes with these UNCHANGED; any new net residual means it
        // retained input WETH or skimmed acquired stock. Comparing to the pre-call balance (not zero)
        // means pre-existing unsolicited balances at the adapter never brick execution.
        v.adapterWethBefore = weth.balanceOf(address(acquisitionAdapter));
        v.adapterStockBefore = IERC20(stockToken).balanceOf(address(acquisitionAdapter));

        // Approve only the immutable adapter, only for the exact input, then clear after the call.
        weth.forceApprove(address(acquisitionAdapter), wethAmountIn);
        v.reported = acquisitionAdapter.acquireStock(
            stockToken, wethAmountIn, minStockOut, deadline, executionData
        );
        weth.forceApprove(address(acquisitionAdapter), 0);

        // Independent verification: exact WETH spend, actual stock delta, report == observed.
        uint256 spent = v.wethBefore - weth.balanceOf(address(this));
        if (spent != wethAmountIn) revert WethSpendMismatch(wethAmountIn, spent);

        v.actualStockOut = IERC20(stockToken).balanceOf(address(this)) - v.stockBefore;
        if (v.actualStockOut != v.reported) {
            revert ReportedStockMismatch(v.reported, v.actualStockOut);
        }
        if (v.actualStockOut < minStockOut) {
            revert MinimumStockOutNotMet(minStockOut, v.actualStockOut);
        }

        // No NEW net residual custody at the adapter: it must not finish holding more WETH (retained
        // input) or more selected stock (skimmed output) than it held before the call. This closes the
        // gap where exact-spend, report==observed, and minimum checks all pass yet the adapter kept
        // WETH or extra stock. Pre-existing donations are tolerated (compared to the pre-call balance).
        uint256 adapterWethAfter = weth.balanceOf(address(acquisitionAdapter));
        if (adapterWethAfter != v.adapterWethBefore) {
            revert ResidualWethInAdapter(v.adapterWethBefore, adapterWethAfter);
        }
        uint256 adapterStockAfter = IERC20(stockToken).balanceOf(address(acquisitionAdapter));
        if (adapterStockAfter != v.adapterStockBefore) {
            revert ResidualStockInAdapter(v.adapterStockBefore, adapterStockAfter);
        }

        // Frozen 80/20 split: floor to distribution, entire remainder to reserve.
        v.distributionAllocation =
            Math.mulDiv(v.actualStockOut, DISTRIBUTION_PERCENT, SPLIT_DENOMINATOR);
        v.reserveAllocation = v.actualStockOut - v.distributionAllocation;

        totalWethSpent += wethAmountIn;
        totalStockAcquired[stockToken] += v.actualStockOut;
        distributionAllocated[stockToken] += v.distributionAllocation;
        reserveAllocated[stockToken] += v.reserveAllocation;

        emit StockAcquired(
            msg.sender,
            stockToken,
            wethAmountIn,
            v.actualStockOut,
            v.distributionAllocation,
            v.reserveAllocation,
            address(acquisitionAdapter)
        );

        // Deliver the reserve portion immediately to the immutable reserve recipient, verifying BOTH
        // sides of the transfer: the vault's stock balance decreases by exactly the reserve amount and
        // the recipient's balance increases by exactly the reserve amount.
        if (v.reserveAllocation > 0) {
            uint256 vaultBefore = IERC20(stockToken).balanceOf(address(this));
            uint256 rBefore = IERC20(stockToken).balanceOf(reserveRecipient);
            IERC20(stockToken).safeTransfer(reserveRecipient, v.reserveAllocation);
            uint256 vaultSent = vaultBefore - IERC20(stockToken).balanceOf(address(this));
            uint256 rReceived = IERC20(stockToken).balanceOf(reserveRecipient) - rBefore;
            if (vaultSent != v.reserveAllocation) {
                revert ReserveDeliveryMismatch(v.reserveAllocation, vaultSent);
            }
            if (rReceived != v.reserveAllocation) {
                revert ReserveDeliveryMismatch(v.reserveAllocation, rReceived);
            }
            emit ReserveAllocated(stockToken, reserveRecipient, v.reserveAllocation);
        }

        return v.actualStockOut;
    }

    // --- Distribution release (executor only, immutable recipient) -------------------------------

    /// @notice Release accounted distribution stock to the immutable DistributionFundingCoordinator.
    /// @dev Executor-only, nonReentrant, fixed recipient (no recipient parameter). Bounded by the
    ///      unreleased distribution allocation so unsolicited donations can never be released. This is
    ///      only the narrow custody-to-coordinator boundary: it does NOT publish or fund any
    ///      `DistributionClaimManager` cycle. Deployment stays blocked until the concrete coordinator
    ///      and the ownership/authorization sequence are finalized (see contract-level NatSpec).
    function releaseToDistributionCoordinator(address stockToken, uint256 amount)
        external
        nonReentrant
    {
        if (msg.sender != acquisitionExecutor) revert NotAuthorizedExecutor();
        if (!isApprovedStockToken[stockToken]) revert StockTokenNotApproved(stockToken);
        if (amount == 0) revert ZeroAmount();

        uint256 releasable = distributionAllocated[stockToken] - distributionReleased[stockToken];
        if (amount > releasable) revert ReleaseExceedsAllocation(amount, releasable);

        // Effects before interaction.
        distributionReleased[stockToken] += amount;

        // Verify BOTH sides: the vault's stock balance decreases by exactly `amount` and the
        // coordinator's balance increases by exactly `amount`.
        uint256 vaultBefore = IERC20(stockToken).balanceOf(address(this));
        uint256 before = IERC20(stockToken).balanceOf(distributionFundingCoordinator);
        IERC20(stockToken).safeTransfer(distributionFundingCoordinator, amount);
        uint256 vaultSent = vaultBefore - IERC20(stockToken).balanceOf(address(this));
        uint256 received = IERC20(stockToken).balanceOf(distributionFundingCoordinator) - before;
        if (vaultSent != amount) revert DistributionDeliveryMismatch(amount, vaultSent);
        if (received != amount) revert DistributionDeliveryMismatch(amount, received);

        emit DistributionReleased(stockToken, distributionFundingCoordinator, amount);
    }

    // --- Views -----------------------------------------------------------------------------------

    /// @notice The frozen approved stock basket.
    function approvedStockTokens() external view returns (address[] memory) {
        return _approvedStockTokens;
    }

    function approvedStockTokenCount() external view returns (uint256) {
        return _approvedStockTokens.length;
    }

    function approvedStockTokenAt(uint256 index) external view returns (address) {
        return _approvedStockTokens[index];
    }

    /// @notice Distribution stock still releasable to the coordinator for `stockToken`.
    function distributionReleasable(address stockToken) external view returns (uint256) {
        return distributionAllocated[stockToken] - distributionReleased[stockToken];
    }

    /// @notice Unattributed WETH custody balance (may include unsolicited donations as well as
    ///         router-delivered budget; the vault does not claim all WETH is protocol-generated).
    function availableWethCustody() external view returns (uint256) {
        return weth.balanceOf(address(this));
    }

    /// @notice Unsolicited (donated) `stockToken` balance beyond the accounted, unreleased
    ///         distribution allocation. Derived from the donation-safe inequality
    ///         `balanceOf(vault) + released >= allocated` (equality only when there are no donations).
    function unsolicitedStockBalance(address stockToken) external view returns (uint256) {
        uint256 accountedInVault =
            distributionAllocated[stockToken] - distributionReleased[stockToken];
        uint256 balance = IERC20(stockToken).balanceOf(address(this));
        return balance > accountedInVault ? balance - accountedInVault : 0;
    }
}

