// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IStockAcquisitionAdapter} from "../interfaces/IStockAcquisitionAdapter.sol";
import {IStockAcquisitionVaultView} from "../interfaces/IStockAcquisitionVaultView.sol";
import {IRialtoRouterRegistry} from "../interfaces/IRialtoRouterRegistry.sol";

/// @title RialtoStockAcquisitionAdapter
/// @notice The production `IStockAcquisitionAdapter` for BPS v1: converts the vault's custodied WETH
///         into an approved stock token by executing a Rialto **allowance-settlement** quote against
///         the current registry-locked taker-submitted swap router (feature ID 2), then forwards the
///         acquired stock to the vault. Non-upgradeable, no owner/setter/pause/sweep/rescue/withdrawal,
///         no proxy/delegatecall/upgrade, no Permit2, no gasless relay, no Universal Router.
/// @dev Trust model. Rialto instructs integrations NOT to modify the returned `tx.data`, so the adapter
///      forwards the unmodified quote calldata via a low-level `call` — but ONLY to the address the
///      registry currently returns for feature 2, and with WETH approved to exactly that router for
///      exactly the input. Safety comes from strict, venue-agnostic invariants that hold regardless of
///      what the calldata encodes: registry-locked target, exact-input WETH consumption, observed
///      stock-delta >= minimum, no new net residual WETH/stock custody at the adapter, cleared
///      approval, and atomic revert on any mismatch. A malicious quote can therefore only reduce output
///      (caught by the minimum) or fail (reverts) — it can never redirect the vault's WETH or credit
///      the wrong asset. There is NO stable settlement selector pinned: the official router ABI/selector
///      was not independently verified in this task, so per the spec the design relies on the
///      registry-locked target plus these invariants rather than guessing a selector (recorded as a
///      config blocker — pin the exact selector once the deployed router ABI is verified).
///
///      DEPLOYMENT IS NOT AUTHORIZED here and the constructor does NOT prove production wiring. The
///      vault↔adapter immutability is circular (the frozen vault stores this adapter immutably and this
///      adapter stores the vault immutably), so the vault address must be a pre-computed
///      (deterministic / nonce-predicted) address bound through a later reviewed deployment procedure
///      that constructs the second contract at exactly the predicted address and verifies both
///      immutables on-chain. The constructor code-checks WETH and the registry (already-deployed
///      dependencies) but intentionally does NOT code-check the vault. The registry ABI, the current
///      feature-2 router, the WETH address, and the approved stock-token addresses are later deployment
///      gates, not construction guarantees. There is NO native-ETH receive/fallback; forced ETH (e.g.
///      via selfdestruct/coinbase) cannot be prevented and, with no recovery path, would remain stuck.
///
///      All assets, addresses, and executions exercised in this repository's tests are fictional and
///      local; nothing here is deployed or connected to any network, and no Rialto API is called.
contract RialtoStockAcquisitionAdapter is IStockAcquisitionAdapter, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice The frozen StockAcquisitionVault — the only permitted caller and the acquired-stock
    ///         recipient. Also the source of the approved stock basket.
    address public immutable stockAcquisitionVault;
    IERC20 public immutable weth;
    IRialtoRouterRegistry public immutable routerRegistry;
    /// @notice Rialto registry feature ID for the active taker-submitted swap router.
    uint256 public constant SWAP_ROUTER_FEATURE_ID = 2;
    /// @notice Robinhood Chain ID (verified from official Rialto/Robinhood Chain documentation). The
    ///         adapter is deployable ONLY on this chain — the fee/allowance-settlement Rialto flow is
    ///         chain-specific and the registry lives here. Not configurable.
    uint256 public constant ROBINHOOD_CHAIN_ID = 4663;

    /// @notice The minimal adapter-specific execution payload carried in `executionData`. It contains
    ///         only the Rialto quote's target and unmodified calldata plus the quote's own expiry —
    ///         no caller-selected value, approval spender, secondary target, or callback.
    struct RialtoExecution {
        address target; // must equal routerRegistry.ownerOf(2)
        bytes callData; // the unmodified Rialto quote tx.data
        uint256 quoteDeadline; // the quote's own expiry (stale quote reverts)
    }

    error ZeroAddress();
    error InvalidSystemAddress();
    error NotAContract(address target);
    error WrongChain(uint256 chainId);
    error NotVault();
    error StockNotApproved(address stockToken);
    error InvalidStock();
    error ZeroAmountIn();
    error ZeroMinimumOutput();
    error ExpiredDeadline();
    error ExpiredQuote();
    error EmptyCallData();
    error RouterFeatureUninitialized();
    error StaleOrWrongRouter(address quoted, address current);
    error InvalidRouterTarget(address target);
    error FundingMismatch(uint256 expected, uint256 actual);
    error RouterCallFailed();
    error MinimumStockOutNotMet(uint256 minimum, uint256 observed);
    error ResidualWethInAdapter(uint256 before, uint256 afterBalance);
    error ResidualStockInAdapter(uint256 before, uint256 afterBalance);
    error ApprovalNotCleared(uint256 remaining);

    /// @param vault_ Immutable StockAcquisitionVault (may be a pre-computed address without code yet —
    ///        see the circular-deployment note in the contract NatSpec).
    /// @param weth_ Immutable WETH token (must already have code).
    /// @param registry_ Immutable Rialto Router Registry (must already have code).
    constructor(address vault_, address weth_, address registry_) {
        // forge-lint: disable-next-line(block-timestamp)
        if (block.chainid != ROBINHOOD_CHAIN_ID) revert WrongChain(block.chainid);
        if (vault_ == address(0) || weth_ == address(0) || registry_ == address(0)) {
            revert ZeroAddress();
        }
        if (weth_ == vault_ || weth_ == registry_ || vault_ == registry_) {
            revert InvalidSystemAddress();
        }
        if (weth_.code.length == 0) revert NotAContract(weth_);
        if (registry_.code.length == 0) revert NotAContract(registry_);

        stockAcquisitionVault = vault_;
        weth = IERC20(weth_);
        routerRegistry = IRialtoRouterRegistry(registry_);
    }

    // Intermediate state held in memory to keep the function within the stack limit.
    struct AcquireVars {
        uint256 adapterWethBefore;
        uint256 adapterStockBefore;
        address router;
        uint256 acquired;
    }

    /// @inheritdoc IStockAcquisitionAdapter
    function acquireStock(
        address stockToken,
        uint256 wethAmountIn,
        uint256 minStockOut,
        uint256 deadline,
        bytes calldata executionData
    ) external nonReentrant returns (uint256) {
        if (msg.sender != stockAcquisitionVault) revert NotVault();
        if (!IStockAcquisitionVaultView(stockAcquisitionVault).isApprovedStockToken(stockToken)) {
            revert StockNotApproved(stockToken);
        }
        if (stockToken == address(weth)) revert InvalidStock();
        if (wethAmountIn == 0) revert ZeroAmountIn();
        if (minStockOut == 0) revert ZeroMinimumOutput();
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp > deadline) revert ExpiredDeadline();

        RialtoExecution memory ex = abi.decode(executionData, (RialtoExecution));
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp > ex.quoteDeadline) revert ExpiredQuote();
        if (ex.callData.length < 4) revert EmptyCallData(); // must carry at least a selector

        AcquireVars memory v;
        // Registry target lock: accept ONLY the current feature-2 router (never prev/next/staged).
        v.router = routerRegistry.ownerOf(SWAP_ROUTER_FEATURE_ID);
        if (v.router == address(0)) revert RouterFeatureUninitialized();
        if (ex.target != v.router) revert StaleOrWrongRouter(ex.target, v.router);
        if (v.router.code.length == 0) revert NotAContract(v.router);
        if (
            v.router == address(routerRegistry) || v.router == stockAcquisitionVault
                || v.router == address(this) || v.router == address(weth) || v.router == stockToken
        ) {
            revert InvalidRouterTarget(v.router);
        }

        v.adapterWethBefore = weth.balanceOf(address(this));
        v.adapterStockBefore = IERC20(stockToken).balanceOf(address(this));

        // Pull exactly `wethAmountIn` from the vault and verify exact receipt (rejects fee-on-transfer).
        weth.safeTransferFrom(stockAcquisitionVault, address(this), wethAmountIn);
        if (weth.balanceOf(address(this)) - v.adapterWethBefore != wethAmountIn) {
            revert FundingMismatch(
                wethAmountIn, weth.balanceOf(address(this)) - v.adapterWethBefore
            );
        }

        v.acquired = _executeQuote(stockToken, wethAmountIn, minStockOut, v, ex);

        // Forward exactly the observed acquired stock to the vault; the adapter must end at baseline.
        IERC20(stockToken).safeTransfer(stockAcquisitionVault, v.acquired);
        uint256 adapterStockAfter = IERC20(stockToken).balanceOf(address(this));
        if (adapterStockAfter != v.adapterStockBefore) {
            revert ResidualStockInAdapter(v.adapterStockBefore, adapterStockAfter);
        }

        return v.acquired; // only the vault-observed acquired amount
    }

    /// @dev Approve only the registry-locked router for exactly `wethAmountIn`, execute the unmodified
    ///      quote calldata with zero native value, clear the approval, and verify exact WETH
    ///      consumption + minimum stock. Extracted to keep `acquireStock` within the stack limit.
    function _executeQuote(
        address stockToken,
        uint256 wethAmountIn,
        uint256 minStockOut,
        AcquireVars memory v,
        RialtoExecution memory ex
    ) internal returns (uint256 acquired) {
        weth.forceApprove(v.router, wethAmountIn);
        // Unmodified Rialto quote calldata, forwarded ONLY to the registry-locked router, zero value.
        (bool ok,) = v.router.call(ex.callData);
        if (!ok) revert RouterCallFailed();
        weth.forceApprove(v.router, 0);

        // Observed acquired stock is authoritative; never trust router return data.
        acquired = IERC20(stockToken).balanceOf(address(this)) - v.adapterStockBefore;
        if (acquired < minStockOut) revert MinimumStockOutNotMet(minStockOut, acquired);
        // WETH must be fully consumed by the swap (adapter back to its pre-call baseline).
        uint256 adapterWethAfter = weth.balanceOf(address(this));
        if (adapterWethAfter != v.adapterWethBefore) {
            revert ResidualWethInAdapter(v.adapterWethBefore, adapterWethAfter);
        }
        uint256 remaining = weth.allowance(address(this), v.router);
        if (remaining != 0) revert ApprovalNotCleared(remaining);
    }
}

src/adapters/UniswapV3BPSSwapAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IBPSSwapAdapter} from "../interfaces/IBPSSwapAdapter.sol";
import {ISwapRouter02} from "../interfaces/ISwapRouter02.sol";

/// @title UniswapV3BPSSwapAdapter
/// @notice The production `IBPSSwapAdapter` for BPS v1: a narrow, non-upgradeable adapter that routes
///         the frozen `BPSTradeRouter`'s BPS↔WETH legs through exactly one Uniswap v3 pool via a
///         single `SwapRouter02.exactInputSingle` call. Everything is immutable — the calling router,
///         the BPS/WETH pair, the SwapRouter02 target, and the pool fee tier. There is no arbitrary
///         path, calldata, target, or fee; no owner, setter, pause, sweep, rescue, withdrawal,
///         delegatecall, proxy, or upgrade; and no multi-hop, Universal Router, or v4 surface.
/// @dev Trust model mirrors the router↔adapter and vault↔adapter hardening already in this repo: the
///      adapter pulls exactly the input, approves only SwapRouter02 for exactly that input and clears
///      it, delivers output straight to the caller-supplied recipient, and independently verifies the
///      recipient's observed balance delta (== the venue's report and >= the minimum) plus that it
///      keeps no new net residual BPS or WETH custody. The frozen `BPSTradeRouter` then repeats its
///      own spend / reported-output / minimum checks, so a lying, short-spending, or misbehaving venue
///      reverts the whole trade atomically.
///
///      DEPLOYMENT IS NOT AUTHORIZED HERE and the constructor does NOT prove production wiring. The
///      router↔adapter immutability is circular: `BPSTradeRouter` stores this adapter immutably and
///      this adapter stores the router immutably, so the router address must be a pre-computed
///      (deterministic / nonce-predicted) address bound through a later reviewed deployment procedure
///      that constructs the second contract at exactly the predicted address and then verifies both
///      immutables on-chain. The constructor code-checks BPS/WETH/SwapRouter02 (already-deployed
///      dependencies) but intentionally does NOT code-check the router, or the cycle could never be
///      constructed. The constructor does NOT verify that `swapRouter02` is the official SwapRouter02,
///      that its factory is official, that a BPS/WETH pool exists, is initialized, uses `poolFee`, or
///      holds liquidity — those are later deployment gates, not construction guarantees.
///
///      All assets, addresses, and swaps exercised in this repository's tests are fictional and local;
///      nothing here is deployed or connected to any network.
contract UniswapV3BPSSwapAdapter is IBPSSwapAdapter, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // --- Immutable configuration -----------------------------------------------------------------

    /// @notice The only address permitted to call `swapExactInput` (the frozen BPSTradeRouter).
    address public immutable bpsTradeRouter;
    IERC20 public immutable bps;
    IERC20 public immutable weth;
    ISwapRouter02 public immutable swapRouter02;
    /// @notice Constructor-frozen v3 pool fee tier. The specific tier is a later product/deployment
    ///         decision; deployment must verify the official factory enables it and that
    ///         `factory.getPool(BPS, WETH, poolFee)` returns the intended pool.
    uint24 public immutable poolFee;

    // SwapRouter02 recipient sentinels (this deployment): address(1) = msg.sender, address(2) = the
    // router itself. Both must be rejected so output can never be silently redirected.
    address private constant MSG_SENDER_SENTINEL = address(1);
    address private constant ROUTER_SELF_SENTINEL = address(2);

    // --- Errors ----------------------------------------------------------------------------------

    error ZeroAddress();
    error InvalidTokenPair();
    error InvalidSystemAddress();
    error ZeroPoolFee();
    error NotAContract(address target);
    error NotBpsTradeRouter();
    error UnsupportedPair(address tokenIn, address tokenOut);
    error SameToken();
    error ZeroAmountIn();
    error ExpiredDeadline();
    error InvalidRecipient(address recipient);
    error FundingMismatch(uint256 expected, uint256 actual);
    error OutputMismatch(uint256 reported, uint256 observed);
    error MinimumOutputNotMet(uint256 minimum, uint256 observed);
    error ResidualBpsInAdapter(uint256 before, uint256 afterBalance);
    error ResidualWethInAdapter(uint256 before, uint256 afterBalance);
    error ApprovalNotCleared(uint256 remaining);
    error NativeTransferNotAllowed();

    /// @param bpsTradeRouter_ Immutable authorized caller (the frozen BPSTradeRouter; may be a
    ///        pre-computed address without code yet — see contract NatSpec on the deployment cycle).
    /// @param bps_ Immutable BPS token (must already have code).
    /// @param weth_ Immutable WETH token (must already have code).
    /// @param swapRouter02_ Immutable Uniswap SwapRouter02 (must already have code).
    /// @param poolFee_ Immutable v3 pool fee tier (nonzero).
    constructor(
        address bpsTradeRouter_,
        address bps_,
        address weth_,
        address swapRouter02_,
        uint24 poolFee_
    ) {
        if (
            bpsTradeRouter_ == address(0) || bps_ == address(0) || weth_ == address(0)
                || swapRouter02_ == address(0)
        ) {
            revert ZeroAddress();
        }
        if (bps_ == weth_) revert InvalidTokenPair();
        // No dangerous aliasing among the system addresses.
        if (swapRouter02_ == bps_ || swapRouter02_ == weth_ || swapRouter02_ == bpsTradeRouter_) {
            revert InvalidSystemAddress();
        }
        if (bpsTradeRouter_ == bps_ || bpsTradeRouter_ == weth_) revert InvalidSystemAddress();
        if (poolFee_ == 0) revert ZeroPoolFee();
        // Code-presence checks for already-deployed dependencies only. The router is intentionally
        // NOT checked (the circular immutability means its predicted address may not host code yet).
        if (bps_.code.length == 0) revert NotAContract(bps_);
        if (weth_.code.length == 0) revert NotAContract(weth_);
        if (swapRouter02_.code.length == 0) revert NotAContract(swapRouter02_);

        bpsTradeRouter = bpsTradeRouter_;
        bps = IERC20(bps_);
        weth = IERC20(weth_);
        swapRouter02 = ISwapRouter02(swapRouter02_);
        poolFee = poolFee_;
    }

    /// @dev Reject direct native-ETH transfers. NOTE: this cannot prevent forced ETH (e.g. via
    ///      `selfdestruct` or a coinbase payment); since there is deliberately no sweep/withdrawal
    ///      path, any such forced balance would remain stuck. The contract's ETH balance is therefore
    ///      not guaranteed to be zero — only that no ordinary transfer or call can add to it here.
    receive() external payable {
        revert NativeTransferNotAllowed();
    }

    // Intermediate swap state held in memory to keep the function within the stack limit.
    struct SwapVars {
        uint256 adapterBpsBefore;
        uint256 adapterWethBefore;
        uint256 recipientOutBefore;
        uint256 reported;
    }

    /// @inheritdoc IBPSSwapAdapter
    /// @dev Exact-input single-pool swap. Only the immutable router may call; only the immutable
    ///      BPS/WETH pair may execute; the deadline is enforced here (SwapRouter02's params carry
    ///      none). Output goes straight to `recipient`; the observed recipient delta is authoritative
    ///      and must equal both the venue's return and (at least) `minimumAmountOut`. The adapter must
    ///      end holding no new net BPS/WETH residual (donation-tolerant) with its venue approval cleared.
    function swapExactInput(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minimumAmountOut,
        address recipient,
        uint256 deadline
    ) external nonReentrant returns (uint256 amountOut) {
        if (msg.sender != bpsTradeRouter) revert NotBpsTradeRouter();

        bool bpsToWeth = tokenIn == address(bps) && tokenOut == address(weth);
        bool wethToBps = tokenIn == address(weth) && tokenOut == address(bps);
        if (!bpsToWeth && !wethToBps) revert UnsupportedPair(tokenIn, tokenOut);
        if (tokenIn == tokenOut) revert SameToken(); // defensive; unreachable given the pair check
        if (amountIn == 0) revert ZeroAmountIn(); // reject SwapRouter02's contract-balance sentinel
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp > deadline) revert ExpiredDeadline();
        _validateRecipient(recipient);

        SwapVars memory v;
        v.adapterBpsBefore = bps.balanceOf(address(this));
        v.adapterWethBefore = weth.balanceOf(address(this));
        v.recipientOutBefore = IERC20(tokenOut).balanceOf(recipient);

        // Pull exactly `amountIn` of tokenIn from the router and verify exact receipt (this rejects
        // fee-on-transfer or otherwise incompatible token behavior).
        IERC20 tin = IERC20(tokenIn);
        uint256 tinBefore = tin.balanceOf(address(this));
        tin.safeTransferFrom(bpsTradeRouter, address(this), amountIn);
        if (tin.balanceOf(address(this)) - tinBefore != amountIn) {
            revert FundingMismatch(amountIn, tin.balanceOf(address(this)) - tinBefore);
        }

        // Approve only SwapRouter02 for exactly `amountIn`, execute one exact-input single swap
        // delivering directly to `recipient`, then clear the approval (extracted to fit the stack).
        v.reported = _venueSwap(tin, tokenIn, tokenOut, amountIn, minimumAmountOut, recipient);

        // The recipient's observed balance delta is authoritative: it must equal the venue's report
        // and meet the minimum. (The frozen router independently repeats both checks.)
        amountOut = IERC20(tokenOut).balanceOf(recipient) - v.recipientOutBefore;
        if (amountOut != v.reported) revert OutputMismatch(v.reported, amountOut);
        if (amountOut < minimumAmountOut) revert MinimumOutputNotMet(minimumAmountOut, amountOut);

        // No new net residual custody at the adapter (compared to pre-call baselines, so pre-existing
        // donations are tolerated but retained input / mis-routed output revert).
        uint256 adapterBpsAfter = bps.balanceOf(address(this));
        if (adapterBpsAfter != v.adapterBpsBefore) {
            revert ResidualBpsInAdapter(v.adapterBpsBefore, adapterBpsAfter);
        }
        uint256 adapterWethAfter = weth.balanceOf(address(this));
        if (adapterWethAfter != v.adapterWethBefore) {
            revert ResidualWethInAdapter(v.adapterWethBefore, adapterWethAfter);
        }

        // The venue approval must be fully cleared.
        uint256 remaining = tin.allowance(address(this), address(swapRouter02));
        if (remaining != 0) revert ApprovalNotCleared(remaining);

        return amountOut;
    }

    /// @dev Approve SwapRouter02 for exactly `amountIn`, perform the single exact-input swap to
    ///      `recipient`, and clear the approval. Extracted to keep `swapExactInput` within the stack
    ///      limit; carries no independent authority (only `swapExactInput` reaches it).
    function _venueSwap(
        IERC20 tin,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minimumAmountOut,
        address recipient
    ) internal returns (uint256 reported) {
        tin.forceApprove(address(swapRouter02), amountIn);
        reported = swapRouter02.exactInputSingle(
            ISwapRouter02.ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                fee: poolFee,
                recipient: recipient,
                amountIn: amountIn,
                amountOutMinimum: minimumAmountOut,
                sqrtPriceLimitX96: 0
            })
        );
        tin.forceApprove(address(swapRouter02), 0);
    }

    /// @dev Reject unsafe recipients: the zero address, both SwapRouter02 sentinels (`address(1)` =
    ///      msg.sender, `address(2)` = router self), this adapter, the SwapRouter02, and either token.
    ///      The immutable BPSTradeRouter IS a valid recipient (the frozen buyback and sell legs use it).
    function _validateRecipient(address recipient) internal view {
        if (
            recipient == address(0) || recipient == MSG_SENDER_SENTINEL
                || recipient == ROUTER_SELF_SENTINEL || recipient == address(this)
                || recipient == address(swapRouter02) || recipient == address(bps)
                || recipient == address(weth)
        ) {
            revert InvalidRecipient(recipient);
        }
    }
}

src/canary/BPSCanaryToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";

/// @title BPSCanaryToken
/// @notice ISOLATED, NON-PRODUCTION canary token for a visibly-labelled Robinhood-mainnet test of the
///         frozen BPS system. It is NOT canonical BPS and carries no official value. Its name and symbol
///         are deliberately distinct ("BPS Canary -- TEST ONLY" / "BPSC-TEST") so it is both technically
///         and visibly distinguishable from canonical BPS on any explorer or wallet.
/// @dev Interface-identical to the frozen `BPSToken` for the surfaces the frozen protocol uses: it is
///      `ERC20` + `ERC20Burnable`, so it satisfies the router's `IBPSBurnable.burn(uint256)` self-burn and
///      every `IERC20` operation the frozen router/vault perform. Fixed 1,000,000,000 supply (18 decimals)
///      is minted exactly once to the constructor recipient; there is NO post-deployment mint path and no
///      privileged control. This file does NOT import, modify, or extend any frozen source; it is a new
///      canary-only contract under `src/canary/`. The production `BPSDeployment` path deploys the concrete
///      `BPSToken` and can never instantiate this type.
contract BPSCanaryToken is ERC20, ERC20Burnable {
    /// @notice Fixed total supply: 1,000,000,000 BPSC-TEST with 18 decimals (matches the canonical size).
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10 ** 18;

    /// @notice Immutable marker distinguishing this canary token from canonical BPS for tooling/tests.
    bool public constant IS_CANARY = true;

    error ZeroRecipient();

    /// @param recipient Non-zero address that receives the entire fixed supply exactly once.
    constructor(address recipient) ERC20(unicode"BPS Canary — TEST ONLY", "BPSC-TEST") {
        if (recipient == address(0)) revert ZeroRecipient();
        _mint(recipient, MAX_SUPPLY);
    }
}

src/interfaces/IBPSBurnable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IBPSBurnable
/// @notice Minimal interface for a token that lets the caller permanently burn its own balance,
///         reducing `totalSupply`. Satisfied by BPSToken via OpenZeppelin `ERC20Burnable.burn`.
/// @dev Only the caller's own balance may be burned; there is no third-party/allowance burn in
///      this interface. The router calls this on the BPS token to burn BPS it repurchased and
///      holds itself, so the reduction is a true `totalSupply` decrease.
interface IBPSBurnable {
    function burn(uint256 amount) external;
}

src/interfaces/IBPSSwapAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IBPSSwapAdapter
/// @notice Narrow swap boundary the router uses for the immutable BPS/WETH pair only. The router
///         binds a single adapter address at construction; callers can never supply a target, pool,
///         path, selector, or calldata. The router pulls the input via an exact, post-use-cleared
///         approval and independently verifies actual balance deltas — it never trusts `amountOut`
///         alone.
/// @dev `swapExactInput` must pull exactly `amountIn` of `tokenIn` from `msg.sender` (the router),
///      deliver the output of `tokenOut` to `recipient`, and return the amount delivered. A lying,
///      short-spending, over/under-reporting, or failing adapter causes the whole trade to revert.
interface IBPSSwapAdapter {
    function swapExactInput(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minimumAmountOut,
        address recipient,
        uint256 deadline
    ) external returns (uint256 amountOut);
}

src/interfaces/IDistributionClaimManager.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IDistributionClaimManagerFunding
/// @notice The single frozen `DistributionClaimManager` entry point the coordinator calls to publish
///         and fund a cycle. Declared as a narrow interface so the coordinator never modifies or
///         imports the frozen manager's implementation. `publishCycle` is `onlyOwner` on the manager
///         and pulls the funded amounts from `msg.sender` (the coordinator) with its own exact
///         balance-delta check, so the coordinator must be the manager's owner and hold/approve the
///         exact stock. The Merkle root, content hashes, and window are governed inputs supplied by
///         the off-chain Proof-of-Distribution boundary; the coordinator never fabricates them.
interface IDistributionClaimManagerFunding {
    function publishCycle(
        uint256 cycleId,
        bytes32 merkleRoot,
        bytes32 allocationsContentHash,
        bytes32 manifestEnvelopeHash,
        uint64 claimStart,
        uint64 claimDeadline,
        address[] calldata assets,
        uint256[] calldata fundedAmounts
    ) external;
}

src/interfaces/IRialtoRouterRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IRialtoRouterRegistry
/// @notice Minimal read-only view of the Rialto Router Registry used to resolve the current active
///         taker-submitted swap router (feature ID 2) on Robinhood Chain.
/// @dev VERIFIED against the official Rialto router-registry documentation
///      (https://docs.rialto.xyz/developers/router-registries): the registry address is
///      `0x71a120CbBf3Ce7cD910a3c50fF77aFc62735687E`; feature ID 2 = the taker-submitted (normal)
///      swap router; and `ownerOf(uint256 featureId)` returns the current active router and **REVERTS
///      when the feature is paused or uninitialized** (it does NOT return a sentinel zero address). The
///      registry also exposes `prev`/`next`/`getFeature(...) -> (previous, current, next, paused)`; the
///      adapter deliberately does NOT use them and accepts ONLY `ownerOf(2)` as an execution target, so
///      a paused/uninitialized feature makes the acquisition **fail closed** (the `ownerOf` call
///      reverts) and a migration to a new router makes a stale quote's target mismatch and revert. The
///      adapter therefore does not need to distinguish paused from uninitialized — both fail closed.
///      (Only `ownerOf` is declared here since it is the only accessor the adapter calls.)
interface IRialtoRouterRegistry {
    /// @notice The current active router for `featureId` (feature ID 2 = taker-submitted swap router).
    ///         REVERTS when the feature is paused or uninitialized. Never returns a sentinel address.
    function ownerOf(uint256 featureId) external view returns (address);
}

src/interfaces/IStockAcquisitionAdapter..content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IStockAcquisitionAdapter
/// @notice Narrow, production-shaped boundary the StockAcquisitionVault uses to convert its custodied
///         WETH into an approved stock token. The vault binds a single adapter address at
///         construction; the caller into the vault can never supply an execution target — the
///         concrete adapter is the only contract the vault ever approves or calls. The vault pulls
///         nothing back and trusts nothing the adapter reports: it independently verifies the exact
///         WETH spent and the actual stock balance delta it observes, and rejects any mismatch.
/// @dev An implementer of `acquireStock` MUST:
///      - perform an exact-input acquisition: consume exactly `wethAmountIn` of WETH pulled from
///        `msg.sender` (the vault) via the allowance the vault grants for exactly that amount;
///      - acquire only the single requested, vault-approved `stockToken` — never a different asset;
///      - deliver the entire acquired output to `msg.sender` (the StockAcquisitionVault);
///      - deliver actual output of at least `minStockOut`;
///      - return `reportedStockOut` equal to the amount the vault will observe as its own
///        `stockToken` balance increase (the vault reverts the whole call if they differ);
///      - never accept, request, or move native ETH;
///      - retain no residual WETH and no residual acquired stock after the call (pass-through custody
///        only — the vault verifies it holds no unexpected residue via its own balance checks);
///      - fail atomically: any shortfall, over/under report, wrong/no delivery, or downstream error
///        must revert the entire call so the vault's WETH is never spent without matching stock.
///
///      `executionData` is an opaque, per-call payload for a later concrete adapter (for example a
///      quote/route blob obtained off-chain). A concrete adapter MUST lock its external execution
///      target to an immutable/registry-resolved address and MUST NOT let `executionData` designate
///      an arbitrary target, recipient, or asset. This generic interface intentionally carries no
///      registry, router, or venue-specific parameters; those belong to the concrete adapter task.
interface IStockAcquisitionAdapter {
    function acquireStock(
        address stockToken,
        uint256 wethAmountIn,
        uint256 minStockOut,
        uint256 deadline,
        bytes calldata executionData
    ) external returns (uint256 reportedStockOut);
}

src/interfaces/IStockAcquisitionVaultOps.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IStockAcquisitionVaultOps
/// @notice The exact slice of the frozen `StockAcquisitionVault` the DistributionFundingCoordinator
///         calls and reads when it occupies BOTH the vault's immutable `acquisitionExecutor` and
///         `distributionFundingCoordinator` roles. Declared as a narrow interface so the coordinator
///         never modifies or imports the frozen vault's implementation. The coordinator derives every
///         recorded amount from the vault's own before/after cumulative-counter deltas — never from a
///         caller-reported value — and executeAcquisition/release are `acquisitionExecutor`-gated, so
///         only the coordinator can move these counters (guaranteeing clean per-acquisition deltas).
interface IStockAcquisitionVaultOps {
    function executeAcquisition(
        address stockToken,
        uint256 wethAmountIn,
        uint256 minStockOut,
        uint256 deadline,
        bytes calldata executionData
    ) external returns (uint256 actualStockOut);

    function releaseToDistributionCoordinator(address stockToken, uint256 amount) external;

    function isApprovedStockToken(address token) external view returns (bool);
    function totalWethSpent() external view returns (uint256);
    function totalStockAcquired(address token) external view returns (uint256);
    function distributionAllocated(address token) external view returns (uint256);
    function reserveAllocated(address token) external view returns (uint256);
    function distributionReleased(address token) external view returns (uint256);
    function DISTRIBUTION_PERCENT() external view returns (uint256);
    function SPLIT_DENOMINATOR() external view returns (uint256);
}

src/interfaces/IStockAcquisitionVaultVie.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IStockAcquisitionVaultView
/// @notice The read-only slice of the frozen `StockAcquisitionVault` that the concrete Rialto adapter
///         and the distribution coordinator depend on. Declared as a narrow interface so those new
///         components never modify or import the frozen vault's implementation — they only observe its
///         approved basket and its cumulative released-distribution accounting as the source of truth.
interface IStockAcquisitionVaultView {
    /// @notice Whether `token` is in the vault's frozen approved stock basket.
    function isApprovedStockToken(address token) external view returns (bool);

    /// @notice Cumulative distribution stock the vault has released to its coordinator for `token`.
    ///         Increases only inside the vault's own `releaseToDistributionCoordinator`, so it is a
    ///         trustworthy on-chain bound on how much the coordinator may fund (never donations).
    function distributionReleased(address token) external view returns (uint256);
}

src/interfaces/ISwapRouter02.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ISwapRouter02 (minimal)
/// @notice The single Uniswap SwapRouter02 function and struct the BPS adapter needs — hand-written to
///         match the deployed `SwapRouter02` (`IV3SwapRouter`) ABI exactly, with no broad Uniswap
///         dependency and no copied implementation. Deliberately excludes Universal Router commands,
///         `multicall`, Permit2, v2 swaps, exact-output, and multi-hop functions.
/// @dev Note vs. v3-periphery `ISwapRouter`: SwapRouter02's `ExactInputSingleParams` has **no
///      `deadline` field** (SwapRouter02 exposes deadline only through its `multicall(uint256
///      deadline, bytes[])` wrapper). The BPS adapter therefore enforces the deadline itself before
///      calling this. `exactInputSingle` is `payable` in the deployed ABI; the adapter calls it with
///      zero value. Recipient sentinels in this SwapRouter02: `address(1)` = msg.sender,
///      `address(2)` = the router itself — the adapter rejects both (and `address(0)`).
interface ISwapRouter02 {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut);
}
